n("קריסטינה", "קריסטינה הוא שם בינלאומי שבא מהמילה היוונית כריסטוס, משוח, והוא נפוץ בשפות רבות של אירופה. ברוסית, באיטלקית ובשפה הספרדית השם מוכר מאוד, ובאנגלית מוכרת גם הצורה כריסטין. בעברית נכתב השם גם באות כ.", ["כריסטינה"])
n("מאל", "מאל הוא שם קצר וחדש, וכנראה הוא צורה של מלי או של שמות אחרים שמתחילים בצליל מא. בערבית המילה מאל פירושה רכוש, אבל השם העברי כנראה לא קשור אליה. השם נדיר, וניתן בעיקר לבנות.", ["מאלי"])
n("קלקידן", "קלקידן הוא שם באמהרית, שפת אתיופיה, ופירושו הבטחה או ברית. שמות רבים באמהרית מביעים רעיון של אמונה ושל קשר. השם נפוץ בקרב יוצאי אתיופיה בארץ, וניתן לבנות.", [])
n("מרינה", "מרינה הוא שם שבא מהמילה הלטינית מרינוס, של הים. השם נפוץ ברוסית, באיטלקית ובשפה הספרדית. בעברית של היום המילה מרינה מתארת גם נמל קטן לסירות ולספינות מפרש.", ["מרין"])
n("צח", "צח היא מילה עברית לצלול, טהור ובהיר, כמו אוויר צח או מים צחים. בשיר השירים מופיע הצירוף צח ואדום, בתיאור של יופי. השם ניתן לבנים, ומוכרת גם צורת הנקבה צחית.", ["צחי", "צחית"])
n("קורין", "קורין הוא שם בינלאומי שבא מהמילה היוונית קורה, עלמה ונערה. השם נפוץ בצרפתית ובאנגלית. בעברית הוא נשמע גם קרוב לקורן, מלשון קרן אור.", ["קורן"])
n("סטיב", "סטיב הוא קיצור אנגלי של סטיבן, שם שבא מהמילה היוונית סטפנוס, כתר. באנגלית סטיב הוא שם בפני עצמו, ומוכר מאוד. השם קצר ופשוט, ונוח במשפחות שחיות בין עברית לאנגלית.", ["סטיבן"])
n("עדאל", "עדאל הוא שם עברי חדש, וכנראה הוא בנוי מהמילים עד ואל, ופירושו עד לאלוהים או עדות של אלוהים. מאותו שורש באים גם השמות עדי ועדיאל. השם ניתן גם לבנים וגם לבנות.", ["עדיאל"])
n("אליהב", "אליהב הוא שם עברי חדש שבנוי מהמילים אלי והב, ופירושו האל שלי נתן. המילה הב היא צורה עתיקה של תן, והיא מוכרת מהעברית הקדומה. השם נדיר, וניתן לבנים.", [])
n("טטיאנה", "טטיאנה הוא שם רוסי שבא מהשם הלטיני טטיוס, שמו של מלך עתיק לפי המסורת הרומית. ברוסית השם נפוץ מאוד, ומוכרת גם צורת החיבה טניה. השם הגיע לארץ עם העלייה מברית המועצות.", [])
n("לאוניד", "לאוניד הוא שם רוסי שבא מהשם היווני לאונידס, שפירושו כמו אריה. השם מוכר מיוון העתיקה, בזכות מלך ספרטה. ברוסית ובאוקראינית השם נפוץ, ומוכרת גם צורת החיבה ליוניה.", [])
n("יבגניה", "יבגניה היא צורת הנקבה של יבגני, שם רוסי שבא מהמילה היוונית לאציל. ברוסית מוכרת גם צורת החיבה ז׳ניה, שמשמשת גם לבנים. השם הגיע לארץ עם העלייה מברית המועצות.", ["יבגני"])
n("מנדי", "מנדי הוא צורת חיבה של מנחם, שהייתה נפוצה בקהילות חסידיות. השם מנחם בא מהשורש נ־ח־ם, נחמה. באנגלית יש שם בצליל זהה, מנדי, שהוא צורת חיבה של אמנדה.", ["מנחם"])
n("אתל", "אתל הוא שם אנגלי שבא מהמילה האנגלית העתיקה לאציל. השם היה נפוץ באנגליה בסוף המאה התשע עשרה. ביידיש יש שם בצליל דומה, אטל, שהוא צורת חיבה של אסתר.", [])
n("אולגה", "אולגה הוא שם סלאבי שבא מהשם הנורדי הלגה, שפירושו קדושה או מבורכת. ברוסית ובאוקראינית השם נפוץ מאוד, והוא מוכר בזכות נסיכה מימי הביניים. מוכרת גם הצורה הגברית אולג.", ["אולג"])
n("אומרי", "אומרי הוא כתיב של עומרי, שם מקראי של מלך ישראל שבנה את העיר שומרון. בכתיב עם האות א השם נשמע קרוב למילים אומר ואמירה. השם ניתן לבנים.", ["עומרי"])
n("צוריה", "צוריה הוא שם עברי שבנוי מהמילים צורי ויה, ופירושו ה׳ הוא הסלע שלי. התמונה של אלוהים כצור, סלע חזק, מוכרת מאוד מהשירה העברית הקדומה. השם ניתן גם לבנים וגם לבנות.", ["צורי", "צוריאל"])
n("לוריאן", "לוריאן הוא שם חדש, וכנראה הוא צירוף של לורי ושל אן, או צורה של לורן. בצרפת לוריאן היא גם שמה של עיר נמל בבריטני. השם ניתן בעיקר לבנות.", [])
n("גידי", "גידי הוא צורת חיבה של גדעון, השופט שהציל את ישראל מהמדיינים. השם גדעון קשור כנראה למילה גדע, כרת. גידי היה נפוץ בארץ בשנות החמישים והשישים.", ["גדעון", "גדי"])
n("גילת", "גילת הוא שם עברי מהמילה גיל, שמחה. מאותו שורש באים גם השמות המוכרים גיל, גילה וגילי. בארץ גילת הוא גם שמו של מושב בנגב.", ["גיל", "גילה"])
n("אשלי", "אשלי הוא שם אנגלי שהיה במקור שם משפחה, ופירושו חורשת עצי מילה. באנגלית השם ניתן גם לבנים וגם לבנות, והיה נפוץ מאוד בשנות התשעים. בעברית הוא נשמע קרוב לאשל, עץ מדברי.", ["אשל"])
n("תאיה", "תאיה הוא שם חדש, וכנראה הוא צורה של תיאה, שם יווני שפירושו אלה. במיתולוגיה היוונית תאיה היא גם שמה של אחת הטיטאניות. השם ניתן בעיקר לבנות.", ["תיאה"])
n("עידית", "עידית היא מילה עתיקה לאדמה המשובחת ביותר, והיא מופיעה בדיני התורה. השם נשמע גם קרוב למילה עדי, תכשיט. השם היה נפוץ בארץ בשנות החמישים והשישים.", ["עדי"])
n("ליסה", "ליסה הוא צורה קצרה של אליזבת, הצורה האירופית של השם העברי אלישבע. השם נפוץ בגרמנית, באנגלית ובשפות הסקנדינביות. ברוסית המילה ליסה פירושה שועלה.", ["ליזה"])
n("אניטה", "אניטה היא צורת חיבה של אנה, בשפה הספרדית ובשפות נוספות. השם אנה בא מהשם העברי חנה, שפירושו חן. השם היה נפוץ באמצע המאה העשרים.", ["אנה"])
n("כריסטינה", "כריסטינה הוא כתיב של קריסטינה, שם בינלאומי שבא מהמילה היוונית כריסטוס, משוח. הכתיב עם האות כ קרוב יותר לכתיב היווני. השם נפוץ בשפות רבות של אירופה.", ["קריסטינה"])
n("אוריאנה", "אוריאנה הוא שם בינלאומי, וכנראה הוא בא מהמילה הלטינית אאורום, זהב, ופירושו זהובה. בשפה הספרדית ובאיטלקית השם מוכר. בעברית הוא נשמע קרוב לאור ולאוריה.", ["אוריאן"])
n("מסרט", "מסרט הוא שם באמהרית, שפת אתיופיה, ופירושו יסוד, הבסיס שעליו בונים. שמות רבים באמהרית מביעים רעיון של יציבות ושל אמונה. השם נפוץ בקרב יוצאי אתיופיה בארץ.", [])
n("רהב", "רהב היא מילה עתיקה לגאווה ולכוח, ובשירה העברית הקדומה היא גם שם של מפלצת ים אגדית. מאותו שורש באה המילה רהבתן, גאוותן. כשם, רהב מביא את הרעיון של עוצמה.", [])
n("אדלינה", "אדלינה היא צורה של אדל, שם שבא מגרמנית עתיקה ופירושו אצילה. השם נפוץ ברוסית, באיטלקית ובשפה הספרדית. בעברית מוכרת גם הצורה הקצרה אלינה.", ["אדל"])
n("נטע-לי", "נטע־לי הוא שם עברי חדש שבנוי משתי מילים, נטע ולי, ופירושו הנטע שלי, השתיל שלי. המילה נטע מתארת צמח צעיר שנשתל באדמה. המקף מפריד בין שני חלקי השם.", ["נטע"])
n("פעריל", "פעריל הוא שם ביידיש, צורת חיבה של פערל, פנינה. ביידיש צורות חיבה רבות נבנו עם הסיומת ל. השם היה נפוץ בקהילות של מזרח אירופה.", ["פערי"])
n("בנאל", "בנאל הוא שם עברי חדש, וכנראה הוא בנוי מהמילים בן ואל, ופירושו בן של אלוהים. השם נשמע קרוב לשמות בניה ובן. השם נדיר, וניתן בעיקר לבנים.", [])
n("יעלת חן", "יעלת חן הוא כינוי שמופיע בספר משלי, בתיאור של אישה אהובה, והיעלה שם היא סמל של חן ושל יופי. היעלים חיים בארץ במדבר יהודה ובנגב. השם נכתב לפעמים כמילה אחת, ולפעמים בשתי מילים.", ["יעל"])
n("שרונה", "שרונה הוא שם עברי שבא מהשרון, מישור החוף של ארץ ישראל. שרונה הייתה גם שמה של מושבה של הטמפלרים בתל אביב, שהיום היא שכונה ומתחם בילוי. השם היה נפוץ בארץ בשנות החמישים.", ["שרון"])
n("דנית", "דנית היא צורת נקבה של דן, שבא מהשורש ד־י־ן, שפוט ודין. מאותו שורש באים גם השמות דניאל ודינה. השם היה נפוץ בארץ בשנות השישים והשבעים.", ["דן", "דנה"])
n("סברינה", "סברינה הוא שם בינלאומי שבא מהשם הלטיני של נהר הסוורן בבריטניה. לפי אגדה עתיקה, זה היה שמה של נערה שטבעה בנהר. השם נפוץ בשפות רבות של אירופה.", [])
n("שיין", "שיין היא המילה היידית ליפה, והיא קרובה למילה הגרמנית שן. ביידיש מוכרים גם השמות שיינא ושיינדל. באנגלית יש שם בצליל זהה, שיין, שמקורו אירי.", ["שינא", "שיינא"])
n("רנאל", "רנאל הוא שם עברי חדש שבנוי מהמילים רן ואל, ופירושו שר לאלוהים. המילה רן באה מהשורש ר־נ־ן, שירה ושמחה. השם ניתן גם לבנים וגם לבנות.", ["רונאל"])
n("ליו", "ליו הוא שם קצר, וכנראה הוא צורה של לאו, שם לטיני שפירושו אריה. בשפות של מזרח אסיה יש לשם צליל דומה עם מקור אחר. השם ניתן גם לבנים וגם לבנות.", ["לאו"])
n("צחי", "צחי הוא צורת חיבה של יצחק, אחד משלושת האבות, ששמו קשור במסורת לצחוק. השם נשמע גם קרוב למילה צח, טהור ובהיר. השם היה נפוץ בארץ בשנות השבעים.", ["צח"])
n("מיקי", "מיקי הוא צורת חיבה של מיכאל ושל מיכל, שמות שבאים מהשאלה מי כאל. באנגלית מיקי הוא שם ידוע, גם בזכות דמות מצוירת מפורסמת. השם ניתן גם לבנים וגם לבנות.", ["מיקה"])
n("ג'רמי", "ג׳רמי הוא הצורה האנגלית של ירמיהו, אחד מגדולי הנביאים. השם ירמיהו פירושו ה׳ ירומם. באנגלית השם נפוץ, ובעברית מוכר גם הכתיב גרמי.", ["ירמיהו", "גרמי"])
n("קלרה", "קלרה הוא שם שבא מהמילה הלטינית קלרוס, בהירה וצלולה. השם נפוץ בשפות רבות של אירופה, ובצרפתית ובאנגלית מוכרת הצורה קלייר. בעברית השם נשמע קרוב למילה קל.", ["קלייר"])
n("קילא", "קילא הוא שם ביידיש, ומקורו לא ברור, ויש שקושרים אותו לשם קיילה. ביידיש שמות רבים מסתיימים באות א. השם היה נפוץ בקהילות של מזרח אירופה.", ["קיילא"])
n("מקדס", "מקדס הוא שם באמהרית, שפת אתיופיה, ופירושו מקדש, מקום קדוש. המילה קרובה למילה העברית מקדש, ושתיהן באות מאותו שורש שמי עתיק. השם נפוץ בקרב יוצאי אתיופיה בארץ.", [])
n("ג'ואל", "ג׳ואל הוא הצורה האנגלית של יואל, שם מקראי שבנוי מהמילים יה ואל. בצרפתית יש צורה דומה, ז׳ואל, שניתנת גם לבנות. השם ניתן גם לבנים וגם לבנות.", ["יואל"])
n("אליסיה", "אליסיה היא צורה של אליס, שם שבא מגרמנית עתיקה ופירושו אצילה. השם נפוץ בשפה הספרדית ובאנגלית. מוכרות גם הצורות אליסה ואליס.", ["אליס", "אליסה"])
n("הילית", "הילית הוא שם עברי חדש שבא מהמילה הילה, טבעת של אור סביב הירח או השמש. מאותה מילה באים גם השמות הילה והילי. השם ניתן לבנות.", ["הילה", "הילי"])
n("יריב", "יריב הוא שם עברי מהשורש ר־י־ב, ופירושו מי שמתמודד ונאבק. מאותו שורש בא גם השם העתיק יהויריב. בעברית החדשה השם היה נפוץ בשנות השישים והשבעים.", [])
n("אלכסה", "אלכסה היא צורה קצרה של אלכסנדרה, צורת הנקבה של אלכסנדר, שם יווני שפירושו מגן על האנשים. השם נפוץ באנגלית ובשפות של מזרח אירופה. מוכרת גם הצורה אלכס.", ["אלכס"])
n("אריא", "אריא היא המילה הארמית לאריה, והיא מופיעה בתלמוד ובתרגומים הארמיים הקדומים. האריה הוא סמל של כוח ושל אומץ. השם ניתן בעיקר לבנות.", ["אריה"])
n("אילונה", "אילונה הוא שם הונגרי, שמקורו כנראה בשם הלנה. בעברית השם נשמע קרוב לאלון ולאילנה, ולכן יש שקוראים בו גם משמעות עברית של עץ. השם ניתן לבנות.", ["אילנה", "אלונה"])
